package com.company.skillplatform.bundle.interfaces;
import com.company.skillplatform.bundle.application.*;import com.company.skillplatform.common.interfaces.PageResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.data.domain.Pageable;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/bundles")public class BundleController{private final BundleService service;private final BundleDownloadService downloads;public BundleController(BundleService s,BundleDownloadService d){service=s;downloads=d;}@PostMapping BundleService.BundleView create(@Valid@RequestBody Request r,Authentication a){return service.create(new BundleService.CreateCommand(r.platform,r.osType,r.rootVersionIds,r.includeDependencies),(Long)a.getPrincipal());}@GetMapping PageResponse<BundleService.BundleView> list(Pageable pageable,Authentication a){return PageResponse.from(service.list((Long)a.getPrincipal(),pageable),v->v);}@GetMapping("/{id}")BundleService.BundleView get(@PathVariable Long id,Authentication a){return service.get(id,(Long)a.getPrincipal());}@GetMapping("/{id}/items")List<BundleService.BundleItemView> items(@PathVariable Long id,Authentication a){return service.items(id,(Long)a.getPrincipal());}@GetMapping("/{id}/download")org.springframework.http.ResponseEntity<org.springframework.core.io.ByteArrayResource> download(@PathVariable Long id,Authentication a){return downloads.download(id,(Long)a.getPrincipal());}public record Request(@NotBlank String platform,@NotBlank@Pattern(regexp="(?i)ANY|WINDOWS|MACOS|LINUX")String osType,@NotEmpty@Size(max=50)List<@NotNull Long> rootVersionIds,boolean includeDependencies){} }
